(function(){
'use strict';
if(window.__SP_L8T3_VOCAB_STANDARD_UI_20260902_V2)return;window.__SP_L8T3_VOCAB_STANDARD_UI_20260902_V2=true;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function hash(text){let h=2166136261;for(const c of String(text||'')){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function stableShuffle(values,seedText){const a=[...(values||[])];let seed=hash(seedText)||1;for(let i=a.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function themeNo(){return Number(window.L8_THEME?.number||document.body?.dataset?.theme||3)}
function taskNo(task){const i=(window.L8_THEME?.tasks||[]).findIndex(t=>String(t?.id)===String(task?.id));return i>=0?i+1:''}
function load(task){return window.L8S.load(themeNo(),task.id,task.items.length)}
function current(task){return window.L8S.nextIndex(themeNo(),task.id,task.items.length)}
function pct(task,state){return Math.round((state.done.length/Math.max(1,task.items.length))*100)}
function head(task,state,icon){const p=pct(task,state);return `<section class="l8-card sp-vs-head"><div class="sp-vs-kicker">Aufgabe ${taskNo(task)}</div><h1>${icon} ${esc(task.title)}</h1><p>${esc(task.instruction)}</p><div class="sp-vs-progress"><span>${state.done.length} von ${task.items.length} fertig</span><strong>${p}%</strong></div><div class="sp-vs-bar"><span style="width:${p}%"></span></div></section>`}
function note(state,index,item){const tries=Number(state.tries?.[index]||0),review=Number(state.review?.[index]||0);if(review===2)return'<div class="sp-vs-note hint">Richtig korrigiert. Diese Aufgabe kommt noch einmal.</div>';if(tries===1)return'<div class="sp-vs-note bad">Noch nicht richtig.</div>';if(tries===2)return `<div class="sp-vs-note hint">${esc(item.hint||'Versuche es noch einmal.')}</div>`;if(tries>=3){const a=Array.isArray(item.answer)?item.answer[0]:item.answer;return `<div class="sp-vs-note hint">Lösung: <strong>${esc(a)}</strong>. Gib sie jetzt selbst ein.</div>`}return''}
function finish(icon,text){document.getElementById('app').innerHTML=`<div class="l8-wrap"><section class="l8-card sp-vs-finish"><div>${icon}</div><h2>Gut gemacht!</h2><p>${esc(text)}</p><a class="l8-btn primary" href="index.html">Zur Übersicht</a></section></div>`}
function listenImage(task){
 const root=document.getElementById('app'),S=window.L8S;if(!root||!S)return false;let state=load(task);if(state.done.length>=task.items.length){finish('👂','Du hast die Wörter gehört und erkannt.');return true}
 const idx=current(task);if(idx==null){finish('👂','Du hast die Wörter gehört und erkannt.');return true}state=load(task);const item=task.items[idx];
 const options=stableShuffle(item.options||[],`${task.id}|${idx}`);
 root.innerHTML=`<div class="l8-wrap">${head(task,state,'👂')}<section class="l8-card sp-t3-vocab-card" data-sp-task-stage><button class="l8-btn l8-audio sp-vs-listen" id="spVsListen" type="button">🔊 Anhören</button><div class="sp-vs-images">${options.map((o,n)=>`<button type="button" class="sp-vs-image" data-vs-image="${esc(o.term)}" aria-label="Bild ${n+1}"><img src="${esc(o.image)}" alt="" onerror="this.closest('button').classList.add('missing');this.hidden=true"><span class="fallback">Bild ${n+1}</span></button>`).join('')}</div>${note(state,idx,item)}</section></div>`;
 document.getElementById('spVsListen')?.addEventListener('click',()=>S.say(item.audioText||'',item.audioFile||''));
 document.querySelectorAll('[data-vs-image]').forEach(btn=>btn.addEventListener('click',()=>{const value=btn.dataset.vsImage;if(S.equal(value,item.answer))S.right(themeNo(),task.id,task.items.length,idx,value);else S.wrong(themeNo(),task.id,task.items.length,idx,value);listenImage(task)}));
 setTimeout(()=>S.say(item.audioText||'',item.audioFile||''),180);
 return true
}
function mic(task,item,idx){
 const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){const input=document.getElementById('spVsInput');input?.focus();return}
 let r;try{r=new R()}catch(e){document.getElementById('spVsInput')?.focus();return}r.lang='de-DE';r.interimResults=false;r.maxAlternatives=5;
 const status=document.getElementById('spVsMicStatus');if(status)status.textContent='Ich höre zu …';
 r.onresult=e=>{const values=Array.from(e.results?.[0]||[]).map(x=>x.transcript).filter(Boolean);const exact=values.find(v=>window.L8S.equal(v,item.answer));checkMeaning(task,item,idx,exact||values[0]||'')};
 r.onerror=()=>{if(status)status.textContent='Mikrofon nicht verfügbar. Schreibe das Wort.'};try{r.start()}catch(e){if(status)status.textContent='Mikrofon nicht verfügbar. Schreibe das Wort.'}
}
function checkMeaning(task,item,idx,value){const S=window.L8S;if(!String(value||'').trim())return;if(S.equal(value,item.answer))S.right(themeNo(),task.id,task.items.length,idx,value);else S.wrong(themeNo(),task.id,task.items.length,idx,value);meaning(task)}
function meaning(task){
 const root=document.getElementById('app'),S=window.L8S;if(!root||!S)return false;let state=load(task);if(state.done.length>=task.items.length){finish('💬','Du hast die Bedeutungen aktiv wiederholt.');return true}
 const idx=current(task);if(idx==null){finish('💬','Du hast die Bedeutungen aktiv wiederholt.');return true}state=load(task);const item=task.items[idx];
 root.innerHTML=`<div class="l8-wrap">${head(task,state,'💬')}<section class="l8-card sp-t3-vocab-card sp-vs-meaning" data-sp-task-stage><div class="sp-vs-meaning-text">${esc(item.prompt)}</div><div class="sp-vs-actions"><button class="l8-btn primary" id="spVsMic" type="button">🎤 Sprechen</button><button class="l8-btn" id="spVsWrite" type="button">✍️ Schreiben</button></div><div class="sp-vs-write" id="spVsWriteBox"><input class="l8-input" id="spVsInput" autocomplete="off" placeholder="Wort schreiben"><button class="l8-btn primary" id="spVsCheck" type="button">Prüfen</button></div><div class="sp-vs-mic-status" id="spVsMicStatus"></div>${note(state,idx,item)}</section></div>`;
 const input=document.getElementById('spVsInput');document.getElementById('spVsMic')?.addEventListener('click',()=>mic(task,item,idx));document.getElementById('spVsWrite')?.addEventListener('click',()=>input?.focus());document.getElementById('spVsCheck')?.addEventListener('click',()=>checkMeaning(task,item,idx,input?.value||''));input?.addEventListener('keydown',e=>{if(e.key==='Enter')checkMeaning(task,item,idx,e.target.value)});return true
}
function install(){if(!window.L8UI||window.L8UI.__spT3VocabStandard)return false;const raw=window.L8UI.taskPage.bind(window.L8UI);window.L8UI.taskPage=function(){const id=new URLSearchParams(location.search).get('task'),task=(window.L8_THEME?.tasks||[]).find(t=>String(t?.id)===String(id));if(task?.spL8T3ListenImage)return listenImage(task);if(task?.spL8T3MeaningProduction)return meaning(task);return raw()};window.L8UI.__spT3VocabStandard=true;return true}
const style=document.createElement('style');style.id='sp-l8t3-vocab-standard-style';style.textContent=`
.sp-vs-head h1{margin:6px 0 8px}.sp-vs-kicker{font-weight:900;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}.sp-vs-progress{display:flex;justify-content:space-between;gap:12px;margin-top:14px;font-weight:850}.sp-vs-bar{height:9px;border-radius:999px;background:#ececf2;overflow:hidden;margin-top:6px}.sp-vs-bar span{display:block;height:100%;background:var(--lesson-main,var(--l8-main,#68539b));border-radius:inherit}.sp-t3-vocab-card{margin-top:16px}.sp-vs-listen{display:block;width:min(360px,100%);margin:0 auto 18px}.sp-vs-images{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.sp-vs-image{aspect-ratio:1/1;border:3px solid var(--lesson-line,var(--l8-line,#dedce5));border-radius:18px;background:#fff;overflow:hidden;cursor:pointer;padding:8px}.sp-vs-image:hover{border-color:var(--lesson-main,var(--l8-main,#68539b));transform:translateY(-1px)}.sp-vs-image img{width:100%;height:100%;object-fit:contain}.sp-vs-image .fallback{display:none;font-weight:900}.sp-vs-image.missing .fallback{display:grid;place-items:center;height:100%}.sp-vs-meaning-text{font-size:clamp(22px,3vw,30px);font-weight:950;line-height:1.35;text-align:center;padding:20px 10px}.sp-vs-actions{display:flex;gap:10px;justify-content:center;margin:12px auto;max-width:560px}.sp-vs-actions .l8-btn{flex:1}.sp-vs-write{display:flex;gap:8px;max-width:620px;margin:12px auto}.sp-vs-write input{flex:1}.sp-vs-mic-status{text-align:center;font-weight:800;color:var(--muted);min-height:24px}.sp-vs-note{margin-top:14px;padding:10px 12px;border-radius:12px;font-weight:800}.sp-vs-note.bad{background:#fff0f0;color:#9d2828}.sp-vs-note.hint{background:#fff8dc;color:#725500}.sp-vs-finish{text-align:center}.sp-vs-finish>div:first-child{font-size:56px}@media(max-width:680px){.sp-vs-images{grid-template-columns:1fr}.sp-vs-image{max-width:330px;width:100%;margin:0 auto}.sp-vs-actions,.sp-vs-write{display:grid}.sp-vs-actions .l8-btn{width:100%}}
`;if(!document.getElementById(style.id))document.head.appendChild(style);window.L8T3VocabStandardUI={install,listenImage,meaning};install();
})();
